import { useNavigate } from "react-router-dom";
import Navbar from "../../components/Navbar";

const ProfessionalSVG = () => (
  <svg width="34" height="34" viewBox="0 0 34 34" fill="none">
    <circle cx="17" cy="10" r="5" fill="#1b2d52" opacity="0.85" />
    <path d="M8 28 C8 21.4 12.0 18 17 18 C22.0 18 26 21.4 26 28" fill="#1b2d52" opacity="0.85" />
    <path d="M22 26 L26 22 L30 24" stroke="#96192c" strokeWidth="1.6" strokeLinecap="round" strokeLinejoin="round" />
    <circle cx="26" cy="22" r="1.4" fill="#96192c" />
  </svg>
);

const BusinessSVG = () => (
  <svg width="34" height="34" viewBox="0 0 34 34" fill="none">
    <rect x="6" y="14" width="22" height="16" rx="1.5" fill="#96192c" opacity="0.85" />
    <path d="M4 14 L17 5 L30 14" fill="#96192c" opacity="0.6" stroke="#96192c" strokeWidth="0.5" />
    <rect x="13.5" y="21" width="7" height="9" rx="1" fill="#f7f5f1" />
    <rect x="8" y="17" width="5" height="4" rx="0.8" fill="rgba(247,245,241,0.55)" />
    <rect x="21" y="17" width="5" height="4" rx="0.8" fill="rgba(247,245,241,0.55)" />
    <line x1="17" y1="2" x2="17" y2="6" stroke="#96192c" strokeWidth="1.4" strokeLinecap="round" />
    <path d="M17 2 L22 3.8 L17 5.5Z" fill="#b5902e" />
  </svg>
);

const profFeatures = [
  "Build a verified skill profile",
  "Apply to jobs or receive requests",
  "Offer services across all 58 wilayas",
  "Earn reviews and build your reputation",
];

const bizFeatures = [
  "Post job openings and manage applicants",
  "Browse and search verified professionals",
  "Commission freelancers for specific projects",
  "Build a verified enterprise profile",
];

function RoleCard({ type, icon, badge, title, desc, features, btnLabel, onClick }) {
  const isPro = type === "professional";

  return (
    <div
      className={`
        flex-1 bg-white rounded-2xl border border-gray-200 p-7
        flex flex-col
        border-l-4 border-l-transparent
        transition-all duration-300
        hover:border-l-4
        hover:translate-y-1
        hover:shadow-lg
        ${isPro
          ? "hover:border-l-navy hover:shadow-navy/10"
          : "hover:border-l-red hover:shadow-red/10"
        }
      `}
    >
      {/* Header */}
      <div className="flex items-center gap-3 mb-5">
        {icon}
        <span
          className={`text-[11px] tracking-widest font-semibold px-3 py-1 rounded-full
            ${isPro ? "text-navy bg-blue-50" : "text-red bg-red-50"}`}
        >
          {badge}
        </span>
      </div>

      {/* Title */}
      <h2 className="font-serif text-xl font-normal text-center mb-3">{title}</h2>

      {/* Description */}
      <p className="text-sm text-gray-500 text-center leading-relaxed mb-5">{desc}</p>

      {/* Features */}
      <ul className="list-disc pl-4 flex flex-col gap-2 mb-7 flex-1">
        {features.map((f) => (
          <li key={f} className="text-sm text-gray-800">{f}</li>
        ))}
      </ul>

      {/* Button */}
      <button
        onClick={onClick}
        className={`
          w-full py-3 rounded-full border text-sm font-medium transition-all duration-200
          ${isPro
            ? "border-gray-800 text-gray-800 hover:bg-gray-700 hover:text-white hover:border-gray-700"
            : "border-red text-red hover:bg-red hover:text-white"
          }
        `}
      >
        {btnLabel}
      </button>
    </div>
  );
}

export default function LandingPage() {
  const navigate = useNavigate();

  return (
    <div className="min-h-screen bg-cream">
      <Navbar />

      <div className="flex flex-col items-center px-6 pt-16 pb-12 text-center">
        <p className="text-[11px] tracking-widest text-gray-400 uppercase mb-4">
          Algeria's Professional Network
        </p>

        <h1 className="font-serif text-6xl font-normal leading-tight mb-6">
          Connect <span className="text-red">talent</span>
          <br />
          with <em className="text-navy not-italic">opportunity</em>
        </h1>

        <p className="text-base text-gray-500 max-w-lg leading-relaxed mb-14">
          WorkBridge DZ bridges skilled professionals and Algerian businesses
          <br />— verified, transparent, and built for every wilaya.
        </p>

        {/* Cards */}
        <div className="flex gap-6 max-w-3xl w-full mb-8">
          <RoleCard
            type="professional"
            icon={<ProfessionalSVG />}
            badge="PROFESSIONAL"
            title={<>I am a <strong>Professional</strong></>}
            desc="A skilled individual ready to build a verified presence, attract opportunities, and grow a professional reputation across Algeria."
            features={profFeatures}
            btnLabel="Continue as Professional →"
            onClick={() => navigate("/professional/onboarding/account")}
          />
          <RoleCard
            type="business"
            icon={<BusinessSVG />}
            badge="BUSINESS"
            title={<>I represent a <strong>Business</strong></>}
            desc="An organization looking to hire employees, discover freelance talent, and build a trusted presence on Algeria's professional network."
            features={bizFeatures}
            btnLabel="Continue as Business →"
            onClick={() => navigate("/register")}
          />
        </div>

        <p className="text-sm text-gray-500">
          Already have an account?{" "}
          <span
            className="text-navy underline cursor-pointer"
            onClick={() => navigate("/sign-in")}
          >
            Sign in
          </span>
        </p>

        <p className="text-xs text-gray-300 mt-10">
          © 2026 WorkBridge DZ. All rights reserved.
        </p>
      </div>
    </div>
  );
}
